style:
:root{
  --ink:#0b1823; --gold:#b28a45; --gold-soft:#dcc79e;
  --paper:#f1f2ee; --paper-2:#e6e8e2; --verm:#b0392a;
  --muted:#6b7480; --rule:rgba(11,24,35,.14);
  --serif:'Nanum Myeongjo','NanumMyeongjo','AppleMyungjo','Batang','Noto Serif KR',serif;
  --sans:'Pretendard','Apple SD Gothic Neo','Malgun Gothic','NanumBarunGothic','Noto Sans KR',sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;overflow-x:hidden}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);
  font-size:16px;line-height:1.7;letter-spacing:-.01em;word-break:keep-all;overflow-wrap:break-word;
  overflow-x:hidden;-webkit-font-smoothing:antialiased}
img,table{max-width:100%}
.wrap{max-width:1040px;margin:0 auto;padding:0 22px;width:100%}
.num{font-variant-numeric:tabular-nums;font-feature-settings:"tnum"}
.pg{background-image:linear-gradient(to bottom,rgba(11,24,35,.04) 1px,transparent 1px);background-size:100% 46px}
.sec-no{font-family:var(--serif);font-weight:800;font-size:11.5px;letter-spacing:.28em;color:var(--gold);display:block;margin-bottom:14px}
h2{font-family:var(--serif);font-weight:800;letter-spacing:-.03em;font-size:clamp(1.4rem,3.4vw,2.3rem);line-height:1.32;margin:0 0 15px}
.sub{max-width:34em;color:#3d4a55;margin:0 0 clamp(26px,3.6vw,38px);font-size:.96rem;line-height:1.8}

/* HERO */
.hero{background:radial-gradient(120% 90% at 84% 4%,#1b3a52 0%,rgba(27,58,82,0) 58%),var(--ink);
  color:#eef1ee;padding:0 0 clamp(42px,5.5vw,68px)}
.htop{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;
  padding:18px 0 14px;border-bottom:1px solid rgba(255,255,255,.15);font-size:11.8px;
  letter-spacing:.03em;color:#9dabb6;line-height:1.6}
.htop b{color:#eef1ee;font-weight:700}
.htop .r{text-align:right;flex:0 0 auto}
.hbody{padding-top:clamp(32px,5vw,58px);position:relative}
.kick{font-size:10.8px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);font-weight:700;margin:0 0 18px}
h1{font-family:var(--serif);font-weight:800;font-size:clamp(1.95rem,6.4vw,4.7rem);
  line-height:1.12;letter-spacing:-.035em;margin:0;color:#f4f4ef;max-width:15em}
h1 em{font-style:normal;color:var(--gold-soft)}
.hrule{width:58px;height:3px;background:var(--gold);margin:clamp(18px,2.6vw,28px) 0;border:0}
.hlead{max-width:29em;font-size:clamp(.95rem,1.5vw,1.06rem);line-height:1.85;color:#bcc7cf;margin:0}
.hlead b{color:#fff;font-weight:700}
.hlead + .hlead{margin-top:.85em}
.cue{margin-top:clamp(22px,3vw,32px);display:inline-block;
  font-size:12.2px;letter-spacing:.05em;color:var(--gold-soft);text-decoration:none;
  border-bottom:1px solid rgba(178,138,69,.45);padding-bottom:5px}
.cue:hover{color:#fff;border-bottom-color:#fff}
.stamp{position:absolute;right:0;top:clamp(30px,5vw,54px);width:clamp(88px,12vw,124px);aspect-ratio:1;
  border:3px solid var(--verm);border-radius:3px;display:flex;flex-direction:column;
  align-items:center;justify-content:center;transform:rotate(-7deg);color:var(--verm);
  font-family:var(--serif);font-weight:800;font-size:clamp(10.5px,1.5vw,15px);
  line-height:1.34;letter-spacing:.05em;text-align:center;opacity:.9;pointer-events:none;
  box-shadow:inset 0 0 0 2px rgba(176,57,42,.25)}
.stamp::after{content:"";position:absolute;inset:5px;border:1px solid rgba(176,57,42,.4)}
@media (max-width:900px){
  .stamp{position:static;margin:26px 0 0;transform:rotate(-4deg);width:92px;font-size:10.5px}
}

/* LEDGER */
.ledger{background-color:var(--paper-2);padding:clamp(44px,6.4vw,78px) 0}
.bars{display:grid;gap:14px;margin:0 0 12px}
.brow{display:grid;grid-template-columns:124px minmax(0,1fr);gap:14px;align-items:center}
.blab{font-size:12.5px;line-height:1.4;color:#46515c;font-weight:700;min-width:0}
.blab span{display:block;font-weight:400;font-size:10.6px;color:var(--muted);margin-top:2px;letter-spacing:0}
.btrack{position:relative;background:rgba(11,24,35,.07);height:42px;border-radius:2px;min-width:0}
.bfill{height:100%;display:flex;align-items:center;justify-content:flex-end;
  padding-right:10px;overflow:hidden;border-radius:2px}
.bfill span{white-space:nowrap;font-family:var(--serif);font-weight:800;
  font-size:clamp(12.5px,1.6vw,15.5px);letter-spacing:-.02em}
.gift .bfill{background:var(--paper);border:1px solid rgba(11,24,35,.22);border-right:0;color:#7f8891}
.rate .bfill{background:var(--ink);color:#f0e4cc}
@media (max-width:640px){
  .brow{grid-template-columns:1fr;gap:5px}
  .btrack{height:36px}
  .bfill{justify-content:flex-start;padding-left:10px;padding-right:6px}
}
.bcap{font-size:11.2px;color:var(--muted);margin:0 0 clamp(24px,3.4vw,34px);}

.lossline{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 10px;
  padding:18px 0;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule);
  margin-bottom:clamp(24px,3.4vw,34px)}
.lossline .v{font-family:var(--serif);font-weight:800;font-size:clamp(.92rem,2vw,1.22rem);letter-spacing:-.02em}
.lossline .op{font-family:var(--serif);font-size:1.05rem;color:#9aa3ab}
.lossline .tot{margin-left:auto;color:var(--verm);font-size:clamp(1.15rem,2.9vw,1.8rem)}
@media (max-width:560px){.lossline .tot{margin-left:0}}

.tcard{background:#fff;border:1px solid var(--rule);overflow-x:auto;-webkit-overflow-scrolling:touch}
table{width:100%;border-collapse:collapse;font-size:13.6px;min-width:400px}
caption{text-align:left;padding:14px 16px 12px;font-size:11.6px;color:var(--muted);border-bottom:1px solid var(--rule);line-height:1.6}
caption b{color:var(--ink);font-weight:700}
th,td{padding:10px 13px;text-align:right;border-bottom:1px solid rgba(11,24,35,.07);white-space:nowrap}
th:first-child,td:first-child{text-align:left}
thead th{font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted);font-weight:700;background:#fafbf9}
tbody tr:last-child td{border-bottom:0}
td.rt{font-weight:700}
td.sv{font-weight:800}
tbody tr.mk{background:#fbf7ec}
tbody tr.mk td.sv{color:var(--verm)}
@media (max-width:560px){
  table{font-size:11.4px;min-width:0}
  th,td{padding:8px 7px;white-space:normal}
  thead th{font-size:9px;letter-spacing:0;line-height:1.35}
  caption{font-size:10.6px;padding:11px 11px 9px}
  .tcard{overflow-x:visible}
}
.fine{font-size:11.2px;color:var(--muted);line-height:1.7;margin:11px 0 0;max-width:52em}

/* PROMISE */
.promise{background:var(--ink);color:#e9ecea;padding:clamp(44px,6vw,76px) 0}
.promise .sec-no{color:var(--gold)}
.promise h2{color:#f4f4ef}
.pq{margin:0 0 clamp(20px,2.8vw,30px);font-family:var(--serif);font-weight:800;
  font-size:clamp(1.15rem,2.9vw,1.85rem);letter-spacing:-.03em;line-height:1.52;max-width:24em}
.pq em{font-style:normal;color:var(--gold-soft)}
.plist{list-style:none;margin:0;padding:0;counter-reset:pp;max-width:760px}
.plist li{counter-increment:pp;position:relative;padding:14px 0 14px 28px;
  border-top:1px solid rgba(255,255,255,.13);font-size:14px;line-height:1.7;color:#c3ccd4}
.plist li::before{content:counter(pp);position:absolute;left:0;top:14px;
  font-family:var(--serif);font-weight:800;font-size:12.5px;color:var(--gold)}
.plist b{display:block;color:#fff;font-weight:700;margin-bottom:2px;letter-spacing:-.01em;font-size:14.4px}
.plist li.fail{background:rgba(176,57,42,.13);margin:0 -12px;padding-left:40px;padding-right:12px;border-top-color:rgba(232,136,124,.3)}
.plist li.fail::before{left:12px;color:#e8887c}
.plist li.fail b{color:#f2968a}
.pnum{margin:clamp(22px,3vw,30px) 0 0;font-size:12.8px;color:#93a1ab;line-height:1.8}
.pnum b{color:var(--gold-soft);font-weight:800;font-variant-numeric:tabular-nums}

/* DSR */
.dsr{background-color:var(--paper);padding:clamp(44px,6vw,76px) 0}
.dstats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:clamp(24px,3.4vw,34px)}
.dstat{border-top:2px solid var(--ink);padding-top:12px;min-width:0}
.dstat .n{font-family:var(--serif);font-weight:800;font-size:clamp(1.12rem,2.5vw,1.7rem);
  letter-spacing:-.03em;line-height:1.15;display:block;color:var(--verm);overflow-wrap:anywhere}
.dstat .l{font-size:12.2px;font-weight:700;margin-top:7px;line-height:1.55;display:block;color:#2b3742}
@media (max-width:900px){.dstats{grid-template-columns:1fr;gap:12px}}

.sc{background:var(--ink);color:#eef1ee;border:1px solid rgba(255,255,255,.14)}
.sch{padding:clamp(16px,2.4vw,24px) clamp(15px,2.4vw,26px) 0}
.sk{font-size:10.2px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold-soft);font-weight:700}
.sch h3{font-family:var(--serif);font-weight:800;font-size:clamp(1rem,2.3vw,1.4rem);
  letter-spacing:-.025em;margin:7px 0 5px;color:#f4f4ef;line-height:1.4}
.sch p{font-size:12px;color:#93a1ab;margin:0;line-height:1.7}
.scb{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(14px,2.4vw,28px);
  padding:clamp(16px,2.4vw,24px) clamp(15px,2.4vw,26px)}
@media (max-width:820px){.scb{grid-template-columns:1fr}}
.scf{margin-bottom:16px;min-width:0}
.scf:last-child{margin-bottom:0}
.scf label{display:flex;justify-content:space-between;align-items:baseline;gap:10px;
  font-size:11.2px;letter-spacing:.04em;color:#9dabb6;font-weight:700;margin-bottom:9px}
.scf label output{font-family:var(--serif);font-size:1.05rem;font-weight:800;color:var(--gold-soft);
  letter-spacing:-.02em;font-variant-numeric:tabular-nums;white-space:nowrap}
.scf label em{font-style:normal;font-weight:400;font-size:10.2px;color:#7b8993;display:block}
input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:2px;
  background:rgba(255,255,255,.24);outline:none;margin:0}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;
  border-radius:50%;background:var(--gold-soft);border:5px solid var(--ink);cursor:pointer;
  box-shadow:0 0 0 1px var(--gold-soft)}
input[type=range]::-moz-range-thumb{width:12px;height:12px;border-radius:50%;background:var(--gold-soft);
  border:4px solid var(--ink);cursor:pointer;box-shadow:0 0 0 1px var(--gold-soft)}
input[type=range]:focus-visible{outline:2px solid var(--gold-soft);outline-offset:7px}
.sseg{display:flex;border:1px solid rgba(255,255,255,.28);border-radius:2px;overflow:hidden}
.sseg button{flex:1;min-width:0;border:0;border-right:1px solid rgba(255,255,255,.18);
  background:transparent;color:#a9b6c0;padding:9px 2px;font-size:11px;font-weight:700;
  font-family:var(--sans);cursor:pointer;letter-spacing:-.02em}
.sseg button:last-child{border-right:0}
.sseg button.on{background:var(--gold-soft);color:var(--ink)}
.sseg button:focus-visible{outline:2px solid var(--verm);outline-offset:-2px}
.sres{border:1px solid rgba(255,255,255,.18);padding:clamp(13px,2vw,18px);
  display:flex;flex-direction:column;min-width:0}
.svd{font-family:var(--serif);font-weight:800;font-size:clamp(1.05rem,2.6vw,1.55rem);
  letter-spacing:-.03em;line-height:1.3;padding-bottom:11px;border-bottom:1px solid rgba(255,255,255,.16);
  overflow-wrap:anywhere}
.svd.yes{color:#8fd9b6} .svd.mid{color:var(--gold-soft)} .svd.no{color:#f2968a}
.srows{margin:2px 0 0}
.srows > div{display:flex;justify-content:space-between;align-items:baseline;gap:8px;
  padding:7px 0;border-bottom:1px solid rgba(255,255,255,.08)}
.srows > div:last-child{border-bottom:0}
.srows span{font-size:11.5px;color:#9dabb6;min-width:0}
.srows b{font-family:var(--serif);font-weight:800;font-size:clamp(.86rem,1.5vw,.96rem);
  letter-spacing:-.01em;white-space:nowrap;font-variant-numeric:tabular-nums;flex:0 0 auto}
.snote{font-size:10.5px;color:#7b8993;line-height:1.7;margin:9px 0 13px;overflow-wrap:anywhere}
.snote b{color:#c3ccd4}
.scta{margin-top:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;
  gap:2px;padding:12px 14px;background:#f0ece2;color:var(--ink);text-decoration:none;border:0;
  font-weight:800;transition:background .22s;text-align:center}
.scta:hover{background:var(--gold-soft)}
.scta b{font-size:.94rem}
.scta span{font-size:10.6px;letter-spacing:.04em;opacity:.7}
.scta:focus-visible{outline:2px solid var(--gold-soft);outline-offset:2px}

/* CHECKLIST */
.list{background:var(--paper-2);padding:clamp(44px,6vw,76px) 0}
.qgrid{list-style:none;margin:0;padding:0;border-top:1px solid rgba(11,24,35,.18);
  display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 clamp(22px,3.6vw,40px);
  counter-reset:q}
@media (max-width:760px){.qgrid{grid-template-columns:1fr}}
.qgrid li{counter-increment:q;position:relative;padding:15px 0 15px 28px;
  border-bottom:1px solid rgba(11,24,35,.1);font-size:13.8px;line-height:1.66;
  font-weight:700;letter-spacing:-.015em;min-width:0}
.qgrid li::before{content:counter(q,decimal-leading-zero);position:absolute;left:0;top:16px;
  font-family:var(--serif);font-weight:800;font-size:10.5px;letter-spacing:.04em;color:var(--gold)}
.qgrid li small{display:block;font-weight:400;color:#4d5763;font-size:12.2px;
  line-height:1.66;margin-top:3px;letter-spacing:0}
.qgrid li.last{background:var(--ink);color:#eef1ee;padding-left:28px;
  grid-column:1/-1;border-bottom:0;padding-top:17px;padding-bottom:17px}
.qgrid li.last::before{color:var(--gold-soft)}
.qgrid li.last small{color:#a9b6c0}
.free{margin:clamp(20px,2.8vw,28px) 0 0;padding:15px 17px;
  border:1px dashed rgba(11,24,35,.28);font-size:12.6px;line-height:1.76;color:#3d4a55}
.free b{font-weight:700;color:var(--ink)}

/* CTA */
.cta{background:var(--ink);color:#eef1ee;padding:clamp(46px,6.4vw,82px) 0 clamp(34px,4.6vw,52px)}
.cta h2{color:#f4f4ef;font-size:clamp(1.4rem,3.8vw,2.4rem)}
.cta h2 em{font-style:normal;color:var(--gold-soft)}
.cta p{max-width:32em;color:#b3bfc7;margin:0 0 26px;line-height:1.82;font-size:.96rem}
.btns{display:flex;flex-wrap:wrap;gap:11px}
.btn{display:inline-flex;flex-direction:column;justify-content:center;gap:2px;padding:13px 20px;
  text-decoration:none;border:1px solid rgba(255,255,255,.5);
  transition:background .22s,color .22s,border-color .22s;min-width:0}
.btn b{font-size:.95rem;font-weight:800;letter-spacing:.01em}
.btn span{font-size:10.6px;letter-spacing:.04em;opacity:.68}
.btn.solid{background:#f0ece2;color:var(--ink);border-color:#f0ece2}
.btn.solid:hover{background:var(--gold-soft);border-color:var(--gold-soft)}
.btn.ghost{color:#eef1ee}
.btn.ghost:hover{background:rgba(255,255,255,.1)}
.btn:focus-visible{outline:2px solid var(--gold-soft);outline-offset:3px}
.sign{margin-top:clamp(28px,4vw,42px);border-top:1px solid rgba(255,255,255,.18);
  padding-top:17px;display:flex;align-items:flex-end;gap:15px;flex-wrap:wrap}
.sign .nm{font-family:var(--serif);font-weight:800;font-size:1.6rem;letter-spacing:-.02em;color:#f4f4ef;line-height:1}
.sign .wh{font-size:11.6px;color:#8e9ca6;line-height:1.65}
.sign .wh b{color:#c9d2d8}

footer{background:#08131c;color:#7d8b95;font-size:11.2px;line-height:1.85;padding:26px 0 36px}
footer b{color:#c2ccd3;font-weight:700}
footer .fl{display:flex;flex-wrap:wrap;gap:3px 16px;margin-bottom:8px}
footer p{margin:0;max-width:62em}

/* SHEET FIND */
.sheetfind{margin:0 0 26px;padding:18px 19px;border:1px solid rgba(255,255,255,.26);
  background:rgba(255,255,255,.05)}
.sheetfind form{display:flex;flex-wrap:wrap;gap:9px;align-items:stretch}
.sheetfind input{flex:1 1 11em;min-width:0;background:rgba(0,0,0,.28);color:#f4f4ef;
  border:1px solid rgba(255,255,255,.34);padding:12px 14px;font-size:1rem;font-family:var(--sans);
  letter-spacing:.02em;font-variant-numeric:tabular-nums}
.sheetfind input::placeholder{color:#7f8d97}
.sheetfind input:focus{outline:2px solid var(--gold-soft);outline-offset:1px}
.sheetgo{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;
  min-height:62px;padding:15px 20px;background:var(--gold-soft);color:var(--ink);text-decoration:none;
  transition:background .22s;width:100%}
.sheetgo b{font-size:1.06rem;font-weight:800;letter-spacing:-.01em}
.sheetgo span{font-size:11px;letter-spacing:.05em;opacity:.66}
.sheetgo:hover{background:#fff}
.sheetgo:active{background:var(--gold);color:#fff}
.sheetgo:focus-visible{outline:2px solid #fff;outline-offset:3px}
.sheetfind .hd{font-size:10.8px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--gold-soft);font-weight:700;margin:0 0 11px;display:block}
.sheetfind p{margin:11px 0 0;font-size:11.6px;color:#93a1ab;line-height:1.72;max-width:40em}

/* CALC LINK */
.calcline{margin:22px 0 0;padding:16px 17px;border:1px solid rgba(11,24,35,.2);
  background:#fbfbf8;display:flex;flex-wrap:wrap;align-items:center;gap:10px 16px;justify-content:space-between}
.calcline .tx{min-width:0;flex:1 1 15em}
.calcline b{display:block;font-size:13.6px;font-weight:800;letter-spacing:-.01em}
.calcline span{font-size:11.6px;color:var(--muted);line-height:1.6}
.calcline a{flex:0 0 auto;display:inline-flex;flex-direction:column;gap:1px;padding:10px 16px;
  background:var(--ink);color:#f0ece2;text-decoration:none;font-weight:800;font-size:.9rem;
  transition:background .22s}
.calcline a:hover{background:var(--gold)}
.calcline a em{font-style:normal;font-size:10.2px;font-weight:400;opacity:.7;letter-spacing:.04em}
.calcline a:focus-visible{outline:2px solid var(--verm);outline-offset:3px}

/* BIZ */
footer .biz{margin-top:12px;padding-top:11px;border-top:1px solid rgba(255,255,255,.13);
  font-size:10.6px;line-height:1.85;color:#6f7d87;max-width:62em}
footer .biz b{color:#98a5ae}
footer .biz .todo{color:#c9a15e}

  .telnote{display:none;margin:14px 0 0;padding:12px 14px;border:1px solid rgba(255,255,255,.3);
  background:rgba(255,255,255,.07);font-size:12px;line-height:1.7;color:#c3ccd4}
.telnote.on{display:block}
.telnote b{color:#fff;font-size:1.02rem;letter-spacing:.04em;font-variant-numeric:tabular-nums}
.telnote button{margin-top:9px;background:var(--gold-soft);color:var(--ink);border:0;
  padding:10px 16px;font-weight:800;font-size:.86rem;font-family:var(--sans);cursor:pointer}

/* ===== VIEWS ===== */
body[data-view="list"] #home,body[data-view="sheet"] #home{display:none}
.vb{background:#f1f2ee;min-height:100vh;color:var(--ink)}
.vb .bar{position:sticky;top:0;z-index:30;background:var(--ink);color:#eef1ee;
  padding:13px 18px;display:flex;align-items:center;gap:12px}
.vb .bar a{color:var(--gold-soft);text-decoration:none;font-size:12.4px;font-weight:700;
  border-bottom:1px solid rgba(220,199,158,.45);padding-bottom:2px;flex:0 0 auto;min-height:22px}
.vb .bar b{font-family:var(--serif);font-size:1rem;letter-spacing:-.02em;min-width:0}
.vb .in{max-width:700px;margin:0 auto;padding:16px 16px 40px}
.vb .srch{width:100%;padding:13px 15px;font-size:16px;font-family:var(--sans);
  background:#fff;border:1px solid rgba(11,24,35,.24);color:var(--ink);border-radius:0;margin:0 0 4px}
.vb .srch:focus{outline:2px solid var(--gold);outline-offset:-1px}
.vb .cnt{font-size:11.6px;color:var(--muted);padding:9px 2px 4px}
.vb .cnt b{color:var(--ink)}
.vb .dh{padding:17px 2px 6px;font-size:11.6px;letter-spacing:.16em;color:var(--gold);font-weight:800}
.vb a.u{display:grid;grid-template-columns:minmax(4.4em,auto) minmax(0,1fr) auto;gap:11px;
  align-items:center;padding:14px 2px;border-bottom:1px solid rgba(11,24,35,.1);
  text-decoration:none;color:inherit;min-height:56px}
.vb a.u:active{background:#e6e8e2}
.vb a.u .no{font-weight:800;font-size:1rem;letter-spacing:-.02em;white-space:nowrap;
  font-variant-numeric:tabular-nums}
.vb a.u .no em{display:block;font-style:normal;font-size:10.4px;font-weight:400;
  color:var(--muted);margin-top:1px;letter-spacing:0}
.vb a.u .info{font-size:11.4px;color:#4d5763;line-height:1.5;min-width:0}
.vb a.u .pr{text-align:right;font-weight:800;font-size:.9rem;letter-spacing:-.02em;
  white-space:nowrap;font-variant-numeric:tabular-nums}
.vb a.u .pr span{display:block;font-size:10.2px;font-weight:400;color:#1f6b4a;margin-top:1px}
.vb .none{padding:44px 8px;text-align:center;color:var(--muted);font-size:13.4px}

/* ===== SHEET ===== */
.sh{background:#fff;border:1px solid rgba(11,24,35,.16);padding:22px 20px;margin:14px 0 0}
.sh .shh{border-bottom:2px solid var(--ink);padding-bottom:11px;margin-bottom:15px;
  display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap}
.sh .shh .l{min-width:0}
.sh .shh .br{font-size:9.4px;letter-spacing:.2em;color:var(--gold);font-weight:800;display:block;margin-bottom:5px}
.sh .shh h2{font-family:var(--serif);font-size:1.22rem;margin:0;letter-spacing:-.03em;line-height:1.3}
.sh .shh .r{text-align:right;font-size:10.4px;color:var(--muted);line-height:1.5;flex:0 0 auto}
.sh .shh .r b{color:var(--ink);font-size:12px;display:block}
.sh .unit{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:15px}
.sh .unit .big{font-family:var(--serif);font-size:1.5rem;font-weight:800;letter-spacing:-.03em}
.sh .unit .tag{font-size:11px;color:var(--muted);border:1px solid var(--rule);padding:2px 7px}
.sh table{width:100%;border-collapse:collapse;font-size:12.2px;margin-bottom:15px;min-width:0}
.sh th,.sh td{padding:7px 8px;border-bottom:1px solid rgba(11,24,35,.08);text-align:right;
  font-variant-numeric:tabular-nums}
.sh th:first-child,.sh td:first-child{text-align:left;font-weight:700;color:#33404b;white-space:nowrap}
.sh thead th{background:#f6f7f9;font-size:9.8px;letter-spacing:.05em;color:var(--muted);
  text-transform:uppercase;font-weight:700}
.sh tr.tot td{border-top:2px solid var(--ink);font-weight:800;font-size:13px;background:#fbf8f1}
.sh tr.tot td:first-child{color:var(--ink)}
.sh h3{font-size:10.4px;letter-spacing:.14em;color:var(--gold);font-weight:800;margin:16px 0 7px;
  text-transform:uppercase}
.sh .opt{font-size:11.4px;line-height:1.7;color:#3d4a55;background:#f6f7f9;padding:10px 12px;
  border-left:2px solid var(--gold)}
.sh .fine{font-size:10.2px;color:var(--muted);line-height:1.7;margin:14px 0 0;
  border-top:1px solid var(--rule);padding-top:10px}
.sh .sign{display:flex;justify-content:space-between;align-items:flex-end;gap:14px;
  margin-top:14px;flex-wrap:wrap}
.sh .sign .nm{font-family:var(--serif);font-size:1.16rem;font-weight:800}
.sh .sign .nm em{font-style:normal;font-size:10.4px;font-family:var(--sans);color:var(--muted);
  display:block;font-weight:400;margin-top:2px}
.sh .stamp2{width:66px;height:66px;border:2px solid var(--verm);border-radius:2px;
  transform:rotate(-6deg);color:var(--verm);font-family:var(--serif);font-weight:800;
  font-size:9.6px;line-height:1.35;display:flex;align-items:center;justify-content:center;
  text-align:center;flex:0 0 auto}
.shacts{display:flex;gap:9px;margin:14px 0 0;flex-wrap:wrap}
.shacts button,.shacts a{flex:1 1 8em;min-height:50px;display:flex;align-items:center;
  justify-content:center;background:var(--ink);color:#f0ece2;border:0;text-decoration:none;
  font-family:var(--sans);font-weight:800;font-size:.9rem;cursor:pointer;padding:12px}
.shacts .gh2{background:#fff;color:var(--ink);border:1px solid rgba(11,24,35,.3)}
.telbox{display:flex;gap:9px;margin:14px 0 0;flex-wrap:wrap}
.telbox a,.telbox button{flex:1 1 9em;min-height:52px;display:flex;flex-direction:column;
  align-items:center;justify-content:center;gap:1px;text-decoration:none;border:0;
  font-family:var(--sans);cursor:pointer;padding:10px}
.telbox a{background:var(--ink);color:#f0ece2}
.telbox button{background:#fff;color:var(--ink);border:1px solid rgba(11,24,35,.3)}
.telbox b{font-size:.95rem;font-weight:800}
.telbox span{font-size:10.2px;opacity:.66;letter-spacing:.03em}
.inapp{margin:0 0 14px;padding:11px 13px;background:#fbf3e0;border:1px solid #d8bd84;
  font-size:11.8px;line-height:1.7;color:#5c4a24;display:none}
.inapp.on{display:block}
.inapp b{font-weight:800;color:#3d3018}

@media print{
  body{background:#fff!important}
  #home,.vb .bar,.shacts,.telbox,.inapp,.vb .srch,.vb .cnt{display:none!important}
  body[data-view="sheet"] #v-sheet{display:block!important}
  #v-sheet .in{max-width:none;padding:0}
  .sh{border:0;padding:0;margin:0}
  .sh table{font-size:10.6pt}
  @page{size:A4;margin:12mm}
}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
